from fastapi import FastAPI
from pydantic import BaseModel, EmailStr
import os

app = FastAPI()
port = int(os.getenv('PORT', 3000))

class EmailRequest(BaseModel):
    email: str

@app.post('/validate')
def validate_email(req: EmailRequest):
    import re
    if not re.match(r'^[^\s@]+@[^\s@]+\.[^\s@]+$', req.email):
        return {'error': 'Invalid email format'}
    return {'valid': True, 'email': req.email}

codeTemplate.go:
package main

import (
	"encoding/json"
	"net/http"
	"os"
	"regexp"
)

var emailRegex = regexp.MustCompile(`^[^\s@]+@[^\s@]+\.[^\s@]+$`)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/validate", func(w http.ResponseWriter, r *http.Request) {
		var body struct {
			Email string `json:"email"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		if !emailRegex.MatchString(body.Email) {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusBadRequest)
			json.NewEncoder(w).Encode(map[string]string{"error": "Invalid email format"})
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{"valid": true, "email": body.Email})
	})

	http.ListenAndServe(":"+port, nil)
}

